// Keep only genuinely unanswered questions.
// Discourse counts the original post separately, so reply_count === 0
// means nobody has answered yet. Pinned topics are staff announcements.
const topics = $input.first().json.topic_list?.topics ?? [];

const unanswered = topics
  .filter(t => t.reply_count === 0 && !t.pinned && !t.closed)
  .map(t => ({
    json: {
      id: t.id,
      title: t.title,
      url: `https://community.n8n.io/t/${t.slug}/${t.id}`,
      views: t.views,
      created_at: t.created_at,
      age_hours: Math.round((Date.now() - new Date(t.created_at)) / 36e5),
    },
  }))
  // Oldest first: someone waiting two days needs help more than someone
  // who posted ten minutes ago.
  .sort((a, b) => b.json.age_hours - a.json.age_hours)
  .slice(0, 10);

if (unanswered.length === 0) {
  return [{ json: { empty: true, note: 'No unanswered questions - nothing to draft.' } }];
}

return unanswered;

parameters.text:
=A community member asked this on the n8n forum and nobody has replied for {{ $json.age_hours }} hours.

Title: {{ $json.title }}
Link: {{ $json.url }}

Write a reply that helps them get unstuck. Rules:

1. If you are not confident the answer is correct, say so explicitly and set confidence to "low". A wrong instruction costs more than no instruction.
2. Name the specific nodes involved. No generic advice.
3. If the question is missing information you would need, ask for exactly that instead of guessing.
4. Warm, short, practical. No marketing language.

Return JSON only:
{"topic_area": "...", "confidence": "high|medium|low", "needs_human": true|false, "draft": "..."}

