// Parse the model's JSON and attach the topic it belongs to.
// A model that returns unparseable output is treated as low confidence -
// it must never silently become a confident-looking draft.
const out = [];

for (const [i, item] of $input.all().entries()) {
  const raw = item.json.text ?? item.json.output ?? '';
  const topic = $('Keep unanswered, oldest first').all()[i]?.json ?? {};
  let parsed;

  try {
    parsed = JSON.parse(String(raw).replace(/^```json\s*|\s*```$/g, '').trim());
  } catch {
    parsed = {
      topic_area: 'unknown',
      confidence: 'low',
      needs_human: true,
      draft: String(raw),
      parse_failed: true,
    };
  }

  out.push({
    json: {
      title: topic.title,
      url: topic.url,
      age_hours: topic.age_hours,
      views: topic.views,
      ...parsed,
    },
  });
}

return out;

// Nothing reaches this node without an explicit human approval upstream.
// Kept DISABLED on purpose: accuracy is the product, so posting is a
// deliberate act, not a default. Enable only once the drafts have earned it.
return $input.all();
